[InitializeOnLoad]public static class SouthCoastBeachDetails{const string D="Assets/Scenes/Oasis/SouthBeach/BeachDetails";static SouthCoastBeachDetails(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("SouthCoastBeachDetails.request"))return;File.Delete("SouthCoastBeachDetails.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/SouthCoastBeachDetails.txt",e.ToString());Debug.LogException(e);}}
class Geo{public List<Vector3> p=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<int> ids=new List<int>();public void Tri(Vector3 a,Vector3 b,Vector3 c,bool fabric=false,bool rock=false){int start=p.Count;var norm=Vector3.Cross(b-a,c-a).normalized;foreach(var v in new[]{a,b,c}){p.Add(v);uv.Add(rock?(Mathf.Abs(norm.y)>.5f?new Vector2(v.x/4,v.z/4):Mathf.Abs(norm.x)>.5f?new Vector2(v.z/4,v.y/4):new Vector2(v.x/4,v.y/4)):fabric?new Vector2(.32f+v.x*.036f,.43f+v.z*.036f):new Vector2(.205f+v.x*.004f,.32f+v.y*.04f));}ids.AddRange(new[]{start,start+1,start+2});}public void Box(Vector3 q,Vector3 s){var v=new Vector3[8];for(int i=0;i<8;i++)v[i]=q+Vector3.Scale(new Vector3((i&1)==0?-.5f:.5f,(i&2)==0?-.5f:.5f,(i&4)==0?-.5f:.5f),s);foreach(var f in new[]{new[]{0,2,3,1},new[]{4,5,7,6},new[]{0,1,5,4},new[]{2,6,7,3},new[]{0,4,6,2},new[]{1,3,7,5}}){Tri(v[f[0]],v[f[1]],v[f[2]]);Tri(v[f[0]],v[f[2]],v[f[3]]);}}public void Pole(Vector3 a,Vector3 b,float radius){var axis=(b-a).normalized;var u=Vector3.Cross(axis,Mathf.Abs(axis.y)>.9f?Vector3.forward:Vector3.up).normalized;var vv=Vector3.Cross(axis,u);for(int i=0;i<6;i++){var x=u*Mathf.Cos(i*Mathf.PI/3)+vv*Mathf.Sin(i*Mathf.PI/3);var z=u*Mathf.Cos((i+1)*Mathf.PI/3)+vv*Mathf.Sin((i+1)*Mathf.PI/3);Tri(a+x*radius,a+z*radius,b+x*radius);Tri(a+z*radius,b+z*radius,b+x*radius);}}public Mesh Save(string name){var m=new Mesh{name=name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt16};m.SetVertices(p);m.SetUVs(0,uv);m.SetTriangles(ids,0);m.RecalculateNormals();m.RecalculateBounds();m.RecalculateTangents();m.Optimize();AssetDatabase.CreateAsset(m,D+"/"+name+".asset");return m;}}
static GameObject ObjectWithMesh(string name,Mesh mesh,Material mat){var g=new GameObject(name);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;return g;}static void LOD(GameObject g,Renderer[] near,Renderer[] far=null){var lod=g.AddComponent<LODGroup>();lod.SetLODs(far==null?new[]{new LOD(.012f,near)}:new[]{new LOD(.07f,near),new LOD(.014f,far)});lod.RecalculateBounds();}static List<Vector2> coast;static float[] lengths;static void Along(float s,out Vector2 p,out Vector2 n){int i=1;while(i<lengths.Length-1&&lengths[i]<s)i++;var e=coast[i]-coast[i-1];p=Vector2.Lerp(coast[i-1],coast[i],Mathf.InverseLerp(lengths[i-1],lengths[i],s));n=new Vector2(e.y,-e.x).normalized;p+=n*(11*Mathf.Sin(s/48)+4*Mathf.Sin(s/23+.8f));}
static void Run(){if(AssetDatabase.LoadAssetAtPath<GameObject>(D+"/South Coast Beach Details.prefab"))throw new Exception("Already built; avoid duplicate beach props");Directory.CreateDirectory(D);Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeBeachDetails");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeBeachDetails/Scene.unity",true);var roads=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var shore=roads.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Outer_MEsh");var yard=roads.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var excluded=yard.GetComponent<Renderer>().bounds;excluded.Expand(new Vector3(35,40,35));var hull=File.ReadAllLines("FinalEnvironmentRoadReview/BeachSouthHull.csv").Select(s=>{var a=s.Split(',');return new Vector2(float.Parse(a[0],System.Globalization.CultureInfo.InvariantCulture),float.Parse(a[1],System.Globalization.CultureInfo.InvariantCulture));}).ToList();int start=hull.FindIndex(v=>v.x<0&&v.y>590);coast=new List<Vector2>{new Vector2(0,596.75f)};for(int i=start;i<hull.Count;i++)coast.Add(hull[i]);for(int i=0;i<start&&hull[i].x<0;i++)coast.Add(hull[i]);coast.Add(new Vector2(0,-783.12f));lengths=new float[coast.Count];for(int i=1;i<lengths.Length;i++)lengths[i]=lengths[i-1]+Vector2.Distance(coast[i],coast[i-1]);float length=lengths.Last();
var rockMat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/CoastalTerrain/Crags/Shared Large Granite Faces.mat");rockMat.enableInstancing=true;EditorUtility.SetDirty(rockMat);var rockPaths=new List<string>();for(int variant=0;variant<4;variant++){var geo=new Geo();var random=new System.Random(801+variant);int sides=9;var rings=new Vector3[3,sides];for(int r=0;r<3;r++)for(int k=0;k<sides;k++){float a=k*Mathf.PI*2/sides+(r==1?.13f:0),radius=(r==0?1.9f:r==1?2.2f:1.2f)*(.78f+(float)random.NextDouble()*.4f);rings[r,k]=new Vector3(Mathf.Cos(a)*radius,(r==0?-.55f:r==1?1.1f:2.7f)+(float)random.NextDouble()*.48f,Mathf.Sin(a)*radius*.78f);}for(int r=0;r<2;r++)for(int k=0;k<sides;k++){int j=(k+1)%sides;geo.Tri(rings[r,k],rings[r+1,k],rings[r,j],false,true);geo.Tri(rings[r,j],rings[r+1,k],rings[r+1,j],false,true);}for(int k=0;k<sides;k++)geo.Tri(rings[2,k],new Vector3(.2f,3.2f,-.1f),rings[2,(k+1)%sides],false,true);var rock=ObjectWithMesh("Beach granite boulder "+variant,geo.Save("Beach granite boulder "+variant),rockMat);LOD(rock,new[]{rock.GetComponent<Renderer>()});string path=D+"/Beach Granite Boulder "+variant+".prefab";PrefabUtility.SaveAsPrefabAsset(rock,path);rockPaths.Add(path);UnityEngine.Object.DestroyImmediate(rock);}
var furnitureMat=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="Beach furniture existing Building 02 atlas",enableInstancing=true};furnitureMat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Scenes/Oasis/3D/Texture/Building/Building-02.jpg"));furnitureMat.SetFloat("_Smoothness",.13f);AssetDatabase.CreateAsset(furnitureMat,D+"/Beach furniture existing atlas.mat");var canopy=new Geo();for(int k=0;k<12;k++){float a=k*Mathf.PI/6,b=(k+1)*Mathf.PI/6;var top=new Vector3(0,3.05f,0);var u=new Vector3(Mathf.Cos(a)*1.8f,2.38f,Mathf.Sin(a)*1.8f);var v=new Vector3(Mathf.Cos(b)*1.8f,2.38f,Mathf.Sin(b)*1.8f);canopy.Tri(top,u,v,true);canopy.Tri(top,v,u,true);}canopy.Pole(Vector3.zero,new Vector3(0,3.05f,0),.045f);var group=new GameObject("Beach umbrella and two loungers");var umbrella=ObjectWithMesh("Existing atlas canvas umbrella",canopy.Save("Beach umbrella existing fabric atlas"),furnitureMat);umbrella.transform.SetParent(group.transform,false);var chairs=new Geo();foreach(float x in new[]{-1.1f,1.1f}){for(int k=0;k<8;k++)chairs.Box(new Vector3(x,.48f,-1.05f+k*.17f),new Vector3(.65f,.06f,.12f));for(int k=0;k<6;k++)chairs.Box(new Vector3(x,.53f+k*.13f,.23f+k*.10f),new Vector3(.65f,.09f,.09f));foreach(float xx in new[]{x-.28f,x+.28f}){chairs.Pole(new Vector3(xx,.04f,-1),new Vector3(xx,.47f,-.85f),.035f);chairs.Pole(new Vector3(xx,.04f,.2f),new Vector3(xx,.55f,.2f),.035f);chairs.Pole(new Vector3(xx,.46f,-1.2f),new Vector3(xx,.5f,.3f),.035f);chairs.Pole(new Vector3(xx,.5f,.2f),new Vector3(xx,1.23f,.82f),.035f);}}var seating=ObjectWithMesh("Timber reclining beach chairs",chairs.Save("Beach reclining chair pair atlas"),furnitureMat);seating.transform.SetParent(group.transform,false);LOD(group,group.GetComponentsInChildren<Renderer>(),new[]{umbrella.GetComponent<Renderer>()});PrefabUtility.SaveAsPrefabAsset(group,D+"/Beach Umbrella And Chairs.prefab");UnityEngine.Object.DestroyImmediate(group);
var palm=new GameObject("Existing curved city palm beach prefab");var trunkSource=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/Palm.prefab");var crownSource=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/Palm 1.prefab");var trunk=(GameObject)PrefabUtility.InstantiatePrefab(trunkSource,palm.transform);var crown=(GameObject)PrefabUtility.InstantiatePrefab(crownSource,palm.transform);trunk.transform.localPosition=Vector3.zero;crown.transform.localPosition=crownSource.transform.localPosition-trunkSource.transform.localPosition;foreach(var r in palm.GetComponentsInChildren<Renderer>())foreach(var mat in r.sharedMaterials){mat.enableInstancing=true;EditorUtility.SetDirty(mat);}LOD(palm,palm.GetComponentsInChildren<Renderer>());PrefabUtility.SaveAsPrefabAsset(palm,D+"/Existing Curved City Palm.prefab");UnityEngine.Object.DestroyImmediate(palm);
var probe=new GameObject("Beach temporary surface probe");probe.transform.position=shore.transform.position;probe.transform.rotation=shore.transform.rotation;probe.transform.localScale=shore.transform.lossyScale;var collider=probe.AddComponent<MeshCollider>();collider.sharedMesh=shore.sharedMesh;Physics.SyncTransforms();var root=new GameObject("South Coast Beach Details");var sectors=new Dictionary<int,GameObject>();int rocks=0,palms=0,chairsCount=0;Vector3 sample=Vector3.zero;Func<Vector2,Vector3?> Ground=p=>{var q=new Vector3(p.x,28,p.y);if(excluded.Contains(q))return null;RaycastHit hit;if(!collider.Raycast(new Ray(new Vector3(p.x,100,p.y),Vector3.down),out hit,150)||hit.point.y<25.1f)return null;return hit.point;};Action<string,Vector3,float,int> Place=(path,pos,scale,k)=>{GameObject sector;if(!sectors.TryGetValue(k,out sector)){sector=new GameObject("Beach detail sector "+k);sector.transform.SetParent(root.transform,false);sectors[k]=sector;}var inst=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),sector.transform);inst.transform.position=pos;inst.transform.rotation=Quaternion.Euler(0,(k*71+rocks*39+palms*13)%360,0);inst.transform.localScale*=scale;};for(float s=110;s<length-110;s+=50){Along(s,out var point,out var normal);var p=Ground(point-normal*17);if(p.HasValue){Place(D+"/Existing Curved City Palm.prefab",p.Value,.83f+(palms%4)*.08f,(int)(s/130));palms++;}}
for(float s=125;s<length-125;s+=92){Along(s,out var point,out var normal);for(int j=0;j<2;j++){var p=Ground(point-normal*(j==0?2:8)+new Vector2(normal.y,-normal.x)*(j==0?0:7));if(p.HasValue){Place(rockPaths[rocks%4],p.Value-new Vector3(0,.3f,0),j==0?1.3f:.7f,(int)(s/130));rocks++;}}}
for(float s=190;s<length-170;s+=190){Along(s,out var point,out var normal);var p=Ground(point-normal*26);if(p.HasValue){Place(D+"/Beach Umbrella And Chairs.prefab",p.Value,.95f,(int)(s/130));sample=p.Value;chairsCount++;}}
UnityEngine.Object.DestroyImmediate(probe);foreach(var pair in sectors)PrefabUtility.SaveAsPrefabAssetAndConnect(pair.Value,D+"/Beach Detail Sector "+pair.Key+".prefab",InteractionMode.AutomatedAction);PrefabUtility.SaveAsPrefabAssetAndConnect(root,D+"/South Coast Beach Details.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,new Vector3(-1100,900,-120),new Vector3(-260,25,-90),"Beach-Rocks-Palms-Furniture-Overview"});capture.Invoke(null,new object[]{scene,sample+new Vector3(-27,13,-23),sample+Vector3.up*3,"Beach-Rocks-Palms-Furniture-Closeup"});File.WriteAllText("FinalEnvironmentRoadReview/SouthCoastBeachDetails.txt","SUCCESS red outlined outer coast only; port yard exclusion expanded 35m; terrain-surface raycast placement; granite boulders="+rocks+"; original city palms="+palms+"; umbrella/two-chair groups="+chairsCount+"; spatial sector prefabs="+sectors.Count+".\nExact Shared Large Granite Faces material; original palm meshes/materials/vegetation shader; furniture uses original unchanged Building-02 atlas umbrella/wood regions; no new atlas. Shared instanced materials, low-poly reusable props, sector prefabs, distance LOD and chair culling; no lights/colliders on decoration.");}}
